#include <iostream>
#include <vector>
#include <unordered_set>
#include <unordered_map>
#include <bitset>
#include <queue>
#include <functional>
#include <tuple>
using namespace std;

const int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> P(N, vector<int>(N));
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            cin >> P[i][j];

    using BS = bitset<128>;
    BS init;
    init.set(0);

    // State hashing
    unordered_map<BS, int> state_index;
    vector<BS> index_state;
    queue<pair<BS, int>> bfs_queue;

    state_index[init] = 0;
    index_state.push_back(init);
    bfs_queue.emplace(init, 0);

    while (!bfs_queue.empty()) {
        auto [cur, idx] = bfs_queue.front(); bfs_queue.pop();
        if (idx != state_index[cur]) continue;

        BS derived[7] = {};
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < (1 << N); ++j) {
                if (!(j >> i & 1))
                    derived[i][j | (1 << i)] = derived[i][j] | cur[j];
            }
        }

        for (int mask = 0; mask < (1 << N); ++mask) {
            BS next_state = cur;
            for (int bit = 0; bit < N; ++bit) {
                if (mask >> bit & 1)
                    next_state |= derived[bit];
            }

            if (!state_index.count(next_state)) {
                int new_id = state_index.size();
                state_index[next_state] = new_id;
                index_state.push_back(next_state);
                bfs_queue.emplace(next_state, new_id);
            }
        }
    }

    int total_states = state_index.size();
    vector<vector<int>> trans(total_states, vector<int>(1 << N));

    for (int i = 0; i < total_states; ++i) {
        BS cur = index_state[i];
        BS derived[7] = {};
        for (int j = 0; j < N; ++j) {
            for (int k = 0; k < (1 << N); ++k) {
                if (!(k >> j & 1))
                    derived[j][k | (1 << j)] = derived[j][k] | cur[k];
            }
        }

        for (int mask = 0; mask < (1 << N); ++mask) {
            BS next_state = cur;
            for (int bit = 0; bit < N; ++bit) {
                if (mask >> bit & 1)
                    next_state |= derived[bit];
            }
            trans[i][mask] = state_index[next_state];
        }
    }

    int inv100 = 1, base = 100, exp = MOD - 2;
    while (exp) {
        if (exp & 1) inv100 = (1LL * inv100 * base) % MOD;
        base = (1LL * base * base) % MOD;
        exp >>= 1;
    }

    vector<vector<long long>> dp(2, vector<long long>(total_states));
    dp[0][state_index[BS().set(0)]] = 1;
    int cur_layer = 0;

    for (int round = 0; round < N; ++round) {
        vector<int> probs(1 << N);
        for (int mask = 0; mask < (1 << N); ++mask) {
            probs[mask] = 1;
            for (int k = 0; k < N; ++k) {
                int coefficient = (mask >> k & 1) ? P[round][k] : (100 - P[round][k]);
                probs[mask] = (1LL * probs[mask] * inv100 % MOD) * coefficient % MOD;
            }
        }

        fill(dp[cur_layer ^ 1].begin(), dp[cur_layer ^ 1].end(), 0);

        for (int s = 0; s < total_states; ++s) {
            if (!dp[cur_layer][s]) continue;
            for (int mask = 0; mask < (1 << N); ++mask) {
                int next_s = trans[s][mask];
                dp[cur_layer ^ 1][next_s] = (dp[cur_layer ^ 1][next_s] + 
                                              dp[cur_layer][s] * probs[mask]) % MOD;
            }
        }

        cur_layer ^= 1;
    }

    BS full;
    full.set();
    cout << dp[cur_layer][state_index[full]] << '\n';

    return 0;
}
